import React, { useEffect, useRef, useState } from "react";

function Generate() {
  const canvasRef = useRef();
  const containerRef = useRef();
  const [imagePaths, setImagePaths] = useState([]);
  const [isFading, setIsFading] = useState(false);
  const position = useRef({ x: 0, y: 0 });
  const offset = useRef({ x: 0, y: 0 });
  const isDragging = useRef(false);

  useEffect(() => {
    const stored = JSON.parse(localStorage.getItem("selectedImages") || "[]").slice(0, 5);
    if (!stored.length) return;
    setImagePaths(stored);
    generateImage(stored);
  }, []);

  const applyGrain = (ctx, width, height) => {
    const imageData = ctx.getImageData(0, 0, width, height);
    for (let i = 0; i < imageData.data.length; i += 4) {
      const grain = Math.random() * 60 - 30;
      imageData.data[i] += grain;
      imageData.data[i + 1] += grain;
      imageData.data[i + 2] += grain;
    }
    ctx.putImageData(imageData, 0, 0);
  };

  const applyGlitch = (ctx, width, height) => {
    for (let i = 0; i < 5; i++) {
      const y = Math.random() * height;
      const heightSlice = Math.random() * 10 + 5;
      const imageData = ctx.getImageData(0, y, width, heightSlice);
      ctx.putImageData(imageData, Math.random() * 20 - 10, y);
    }
  };

  const applyPixelation = (ctx, canvas, blockSize = 6) => {
    const width = canvas.width;
    const height = canvas.height;
    const imageData = ctx.getImageData(0, 0, width, height);
    const data = imageData.data;

    for (let y = 0; y < height; y += blockSize) {
      for (let x = 0; x < width; x += blockSize) {
        const i = (y * width + x) * 4;
        const r = data[i];
        const g = data[i + 1];
        const b = data[i + 2];

        for (let dy = 0; dy < blockSize; dy++) {
          for (let dx = 0; dx < blockSize; dx++) {
            const ni = ((y + dy) * width + (x + dx)) * 4;
            if (ni < data.length) {
              data[ni] = r;
              data[ni + 1] = g;
              data[ni + 2] = b;
            }
          }
        }
      }
    }

    ctx.putImageData(imageData, 0, 0);
  };

  const generateImage = async (paths) => {
    const canvas = canvasRef.current;
    const ctx = canvas.getContext("2d");
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    const imgs = await Promise.all(
      paths.map((src) => {
        return new Promise((res) => {
          const img = new Image();
          img.crossOrigin = "anonymous";
          img.onload = () => res(img);
          img.src = src;
        });
      })
    );

    imgs.forEach((img, index) => {
      ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
    });

    applyPixelation(ctx, canvas);
    applyGlitch(ctx, canvas.width, canvas.height);
    applyGrain(ctx, canvas.width, canvas.height);
  };

  return (
    <div
      ref={containerRef}
      style={{ touchAction: "none", overflow: "hidden" }}
    >
      <canvas ref={canvasRef} width={1080} height={1080} />
    </div>
  );
}

export default Generate;
